function UniquePaths(m: int, n: int) -> int {
  let row: int[] = [];
  let j = 0;
  while (j < n) {
    row.push(1);
    j += 1;
  }
  let i = 1;
  while (i < m) {
    let c = 1;
    while (c < n) {
      row[c] = row[c] + row[c - 1];
      c += 1;
    }
    i += 1;
  }
  return row[n - 1];
}
